const u = $input.first().json;
const cb = u.callback_query;
if (cb) {
  return [{ json: {
    kind: 'callback',
    chatId: cb.message?.chat?.id,
    callbackId: cb.id,
    messageId: cb.message?.message_id ?? null,
    serviceId: /^service:\d{1,18}$/.test(cb.data || '') ? Number(cb.data.slice(8)) : null,
    isMenuReturn: cb.data === 'menu'
  }}];
}
const msg = u.message;
return [{ json: {
  kind: (msg?.text || '').trim().split(/\s+/)[0].split('@')[0] === '/start' ? 'start' : 'help',
  chatId: msg?.chat?.id,
  callbackId: null,
  messageId: null,
  serviceId: null,
  isMenuReturn: false
}}];

const ctx = $('Normalize update').first().json;
const all = $input.all().map(x => x.json).filter(x => x && x.id != null);
const upstreamError = $input.all().some(x => x.json?.error != null);
const services = all.flatMap(x => Array.isArray(x) ? x : [x])
  .map(x => ({ id: Number(x.id), name: String(x.name || ''), active: x.active === true }));
const active = services.filter(x => x.active);
const escapeHtml = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
let text = '';
let keyboard = null;
if (upstreamError) {
  text = 'Не удалось загрузить услуги. Попробуйте ещё раз через минуту.';
  keyboard = ctx.kind === 'callback' ? [[{text:'↩️ Вернуться к списку услуг',callback_data:'menu'}]] : null;
} else if (ctx.kind === 'start' || (ctx.kind === 'callback' && ctx.isMenuReturn)) {
  text = active.length
    ? '🛍 Меню услуг\n\nВыберите услугу — бот подтвердит выбор.\nСписок обновляется из базы данных.'
    : 'Сейчас нет доступных услуг. Попробуйте позже.';
  keyboard = active.length ? active.map(x => [{text:x.name, callback_data:'service:' + x.id}]) : null;
} else if (ctx.kind === 'callback') {
  const item = active.find(x => x.id === ctx.serviceId);
  text = item
    ? ('✅ Вы выбрали услугу: ' + escapeHtml(item.name) + '\n\nУслуга найдена по ID в базе данных. Можно вернуться к списку и выбрать другую.')
    : '⚠️ Эта услуга больше недоступна. Меню могло измениться.';
  keyboard = [[{text:'↩️ Вернуться к списку услуг', callback_data:'menu'}]];
} else {
  text = 'Отправьте /start, чтобы увидеть список услуг.';
}
return [{ json: {kind:ctx.kind,chatId:ctx.chatId,callbackId:ctx.callbackId,messageId:ctx.messageId,text,keyboard} }];
